CREATE TABLE inventory.hotel_rooms(id uuid PRIMARY KEY,property_id uuid NOT NULL,code text NOT NULL,name text NOT NULL,max_guests integer NOT NULL CHECK(max_guests BETWEEN 1 AND 20),active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,UNIQUE(property_id,code));
CREATE TABLE inventory.hotel_plans(id uuid PRIMARY KEY,room_id uuid NOT NULL REFERENCES inventory.hotel_rooms(id),name text NOT NULL,refundable boolean NOT NULL,policy text NOT NULL,base_paise bigint NOT NULL CHECK(base_paise>=0),included_guests integer NOT NULL CHECK(included_guests BETWEEN 1 AND 20),extra_guest_paise bigint NOT NULL CHECK(extra_guest_paise>=0),min_stay integer NOT NULL CHECK(min_stay BETWEEN 1 AND 60),active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1);
CREATE TABLE inventory.hotel_days(room_id uuid NOT NULL REFERENCES inventory.hotel_rooms(id),day date NOT NULL,capacity integer NOT NULL CHECK(capacity BETWEEN 0 AND 10000),stop_sell boolean NOT NULL,blackout boolean NOT NULL,PRIMARY KEY(room_id,day));
CREATE TABLE inventory.hotel_rates(plan_id uuid NOT NULL REFERENCES inventory.hotel_plans(id),day date NOT NULL,base_paise bigint NOT NULL CHECK(base_paise>=0),discount_bps integer NOT NULL CHECK(discount_bps BETWEEN 0 AND 10000),min_stay integer NOT NULL CHECK(min_stay BETWEEN 1 AND 60),PRIMARY KEY(plan_id,day));
CREATE TABLE inventory.hotel_allocations(id uuid PRIMARY KEY,sequence bigint GENERATED ALWAYS AS IDENTITY UNIQUE,room_id uuid NOT NULL REFERENCES inventory.hotel_rooms(id),plan_id uuid NOT NULL REFERENCES inventory.hotel_plans(id),owner_id uuid NOT NULL,check_in date NOT NULL,check_out date NOT NULL,quantity integer NOT NULL CHECK(quantity>0),guests_per_room integer NOT NULL CHECK(guests_per_room>0),state text NOT NULL CHECK(state IN ('held','reserved','released','expired')),expires_at timestamptz NOT NULL,quote jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(check_out>check_in));
CREATE INDEX hotel_allocation_capacity ON inventory.hotel_allocations(room_id,check_in,check_out,state);
CREATE TABLE inventory.hotel_requests(actor_id uuid NOT NULL,operation text NOT NULL,key text NOT NULL,fingerprint text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(actor_id,operation,key));
CREATE TABLE inventory.hotel_changes(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,room_id uuid NOT NULL,actor_id uuid NOT NULL,action text NOT NULL,reason text NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION inventory.hotel_history_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Hotel inventory history is immutable'; END $$;
CREATE TRIGGER hotel_changes_immutable BEFORE UPDATE OR DELETE ON inventory.hotel_changes FOR EACH ROW EXECUTE FUNCTION inventory.hotel_history_immutable();

CREATE UNIQUE INDEX hotel_plan_name ON inventory.hotel_plans(room_id,lower(name));
